26-maincol{width:235px}.clinic26 .c26-othercol{width:200px}.clinic26 table.c26-table .c26-top th{background:#963b4b !important;color:#fff !important;font-size:12px;font-weight:700;line-height:1.45 !important}.clinic26 table.c26-table .c26-top .c26-featured{background:#792939 !important}.clinic26 .c26-top-text{display:block}.clinic26 .c26-top-text+.c26-top-text{margin-top:3px}.clinic26 table.c26-table .c26-clinics th{background:#fff7f5 !important}.clinic26 table.c26-table .c26-clinics .c26-featured{background:#ffeaee !important}.clinic26 table.c26-table th.c26-label,.clinic26 table.c26-table th.c26-rowlabel{font-weight:700;white-space:nowrap !important}.clinic26 table.c26-table th.c26-rowlabel{background:#f8e8eb !important;color:#792939 !important;font-size:13px}.clinic26 table.c26-table td.c26-featured{background:#fff3f5 !important}.clinic26 .c26-name{display:block;margin:0 0 6px;color:#792939;font-size:14px;font-weight:800;line-height:1.3}.clinic26 .c26-recommend{display:inline-block;margin-bottom:4px;padding:2px 8px;background:#963b4b;color:#fff;border-radius:20px;font-size:10px;font-weight:700}.clinic26 .c26-banner{display:block;max-width:160px;margin:0 auto 6px;text-decoration:none}.clinic26 .c26-banner a{display:block}.clinic26 .c26-banner img{display:block;width:100% !important;max-width:100% !important;height:auto !important;margin:0 auto;border-radius:5px}.clinic26 .c26-lead{display:block;margin:0 0 4px;color:#963b4b;font-size:11px;font-weight:700;line-height:1.3;white-space:nowrap}.clinic26 a.c26-btn{display:block !important;width:100%;max-width:205px;margin:0 auto !important;padding:9px 5px !important;background:#963b4b !important;color:#fff !important;border:0;border-radius:7px;text-align:center;text-decoration:none !important;font-size:12px;font-weight:700;line-height:1.3 !important;white-space:nowrap;box-shadow:none}.clinic26 a.c26-btn:hover{opacity:.85}.clinic26 a.c26-btn-main{background:#dcef66 !important;color:#34431b !important;border:1px solid #c6d95c !important;box-shadow:0 3px 0 #b7c84f}.clinic26 a.c26-btn-main:hover{background:#c8df45 !important;color:#34431b !important;opacity:1}.clinic26 .c26-head{font-weight:700;line-height:1.4}.clinic26 .c26-head b{font-weight:700}.clinic26 .c26-grade{display:block;margin:0 0 3px;color:#963b4b;font-size:20px;font-weight:800;line-height:1.1}.clinic26 .c26-price{display:block;margin:2px 0 0;color:#963b4b;font-size:20px;font-weight:800;line-height:1.25;white-space:nowrap}.clinic26 .c26-price small{font-size:12px}.clinic26 .c26-sub{display:block;margin-top:3px;color:#71666b;font-size:11px;font-weight:400;line-height:1.4}.clinic26 .c26-em{color:#b32f46;font-weight:800}.clinic26 .c26-mark{display:inline;padding:0 3px;background:#fff0a6;color:#843046;font-weight:700}.clinic26 .c26-nw{display:inline-block}.clinic26 .c26-loan{display:block;margin:5px 0 0;padding:5px;background:#fff;border:1px solid #f0d3d9;border-radius:7px}.clinic26 .c26-loan-row{font-weight:700;line-height:1.3;white-space:nowrap}.clinic26 .c26-arrow{margin:0 3px;color:#b32f46}.clinic26 .c26-monthly{color:#b32f46;font-size:16px;font-weight:800}.clinic26 details.c26-details{display:block;margin-top:5px;background:#fff;border:1px solid #e3bfc6;border-radius:6px;overflow:hidden}.clinic26 .c26-details summary{display:list-item;padding:4px 5px;background:#fbe5e9;color:#792939;font-size:11px;font-weight:700;line-height:1.3;cursor:pointer}.clinic26 .c26-detail-body{display:block;padding:6px;background:#fff;text-align:left;font-size:11px;line-height:1.4}.clinic26 .c26-detail-body div{padding:3px 0;border-bottom:1px solid #f4e6e8}.clinic26 .c26-detail-body div:last-child{border-bottom:0}@media (max-width:767px){.clinic26{margin:12px auto;font-size:11px}.clinic26 .c26-title{font-size:14px;padding:7px 10px !important}.clinic26 .c26-hint{padding:3px;font-size:10px}.clinic26 table.c26-table{width:540px !important;min-width:540px !important}.clinic26 .c26-labelcol{width:50px}.clinic26 .c26-maincol{width:170px}.clinic26 .c26